head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16601";
scwin.result = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16601.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await $c.win.openPopup('/jldfil16601/jldfil16601_layer_layer1.xml', {id:'jldfil16601_layer_layer1', type:'pageFramePopup'}, {});

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16601.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.fnSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16601.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_applList_oncellclick
 * @description grd_applList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_applList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_applList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_applList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.fnWrite(r["comSchdlId"], r["comSchdlTpCd"], r["regYn"], r["applObjLmtYn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_applList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_43_onclick
 * @description krxpage_pagenavigator_43 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_43_onclick = async function (index) {
    try {
    const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; await scwin.fnSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil16601.krxpage_pagenavigator_43_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        target: "dlt_applList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnWrite
 * @description fn Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnWrite = async function () {
    const sbmOptions = {
        id: "tx_fnWrite",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnWriteReq",
        target: "dlt_applList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnApplComCntChk
 * @description fn Appl Com Cnt Chk 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnApplComCntChk = async function () {
    const sbmOptions = {
        id: "tx_fnApplComCntChk",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnApplComCntChkReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplList");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do") */
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnSearch();
};

/**
 * @method
 * @name fnWrite
 * @description fn Write 처리
 * @param {String} ipt_comSchdlId ipt_comSchdlId
 * @param {String} ipt_comSchdlTpCd ipt_comSchdlTpCd
 * @param {String} regYn regYn
 * @param {String} applObjLmtYn applObjLmtYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnWrite = async function (ipt_comSchdlId, ipt_comSchdlTpCd, regYn, applObjLmtYn) {
    if (regYn === 'Y') {
        await $c.win.alert('이미 신청되었습니다.\n신청내역에서 확인하세요.');
        return;
    }
    if (applObjLmtYn === 'Y') {
        const bl = await scwin.fnApplComCntChk(ipt_comSchdlId);
        if (bl === 'false') {
            await $c.win.alert('신청가능한 법인수를 초과하였습니다.\n다음에 신청해주세요.');
            return;
        }
    }
    $c.util.getComponent('ipt_comSchdlId').setValue(ipt_comSchdlId);
    $c.util.getComponent('ipt_comSchdlTpCd').setValue(ipt_comSchdlTpCd);
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplForm");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do") */
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnWrite();
};

/**
 * @method
 * @name layer_popup
 * @description layer popup 처리
 * @param {*} el el
 * @returns {void}
 * @hidden N
 */
scwin.layer_popup = function (el) {
    const $el = $(el);
    const isDim = $el.prev().hasClass('dimBg');
    isDim ? $('.dim-layer').fadeIn() : $el.fadeIn();
    let $elWidth = ~~($el.outerWidth()), $elHeight = ~~($el.outerHeight()), docWidth = $(document).width(), docHeight = $(document).height();
    if ($elHeight < docHeight || $elWidth < docWidth) {
        $elHeight = 900;
        $el.css({ marginTop: -$elHeight / 2, marginLeft: -$elWidth / 2 });
    } else {
        $el.css({ top: 0, left: 0 });
    }
    $el.find('a.btn-layerClose').click(function() {
            isDim ? $('.dim-layer').fadeOut() : $el.fadeOut();
            return false;
    });
    $('.layer .dimBg').click(function() {
            $('.dim-layer').fadeOut();
            return false;
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fnSearch, tx_fnWrite) — 어느 것이 «열자마자» 인지 정할 근거가 없다

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name fnApplComCntChk_done
 * @description fn Appl Com Cnt Chk done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnApplComCntChk_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    bl = scwin.result.returnVal;
};

/**
 * @method
 * @name fnApplComCntChk
 * @description fn Appl Com Cnt Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnApplComCntChk = async function () {
    const r = await scwin.tx_fnApplComCntChk();
    try {
        scwin.fnApplComCntChk_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil16601.fnApplComCntChk' });
    }
    return r;
};
